// 地区 SVG 兜底映射（已清空：所有素材均使用官方 PNG，不再使用自创 SVG）
const REGION_SVG_MAP = {};

/**
 * 根据元素中文名返回其图标 URL（优先官方神瞳 PNG，回退 enka 本地化素材）
 * 全站公用：data.js / regionElementUrl / character-detail.js / character.js 都会用到
 * 注：已移除自创 SVG fallback，所有图标均使用官方素材
 */
function getElementSvgUrl(element) {
  if (ELEMENT_PNG_MAP && ELEMENT_PNG_MAP[element]) return ELEMENT_PNG_MAP[element];
  var iconName = (typeof ELEMENT_CDN_MAP !== 'undefined') && ELEMENT_CDN_MAP[element];
  if (iconName && typeof CDN_BASE !== 'undefined') return CDN_BASE + iconName;
  return '';
}

/**
 * 根据地区 ID 返回其徽章图标
 * 优先级：①官方地区 PNG（REGION_PNG_MAP） ②对应元素神瞳 PNG
 * 注：已移除自创 SVG fallback
 */
function regionElementUrl(regionId) {
  if (REGION_PNG_MAP && REGION_PNG_MAP[regionId]) return REGION_PNG_MAP[regionId];
  var ele = REGION_ELEMENT_MAP[regionId] || '风';
  return getElementSvgUrl(ele);
}

/**
 * 地区徽章图标统一入口：
 *   优先官方七国/地区 PNG 徽章，失败再走 element PNG
 * 与 character.js 中的 getRegionSvgUrl 保持一致
 * 注：已移除自创 SVG fallback
 */
function getRegionSvgUrl(region) {
  if (typeof regionElementUrl !== 'undefined') return regionElementUrl(region);
  if (REGION_PNG_MAP && REGION_PNG_MAP[region]) return REGION_PNG_MAP[region];
  var ele = (typeof REGION_ELEMENT_MAP !== 'undefined')
    ? (REGION_ELEMENT_MAP[region] || '风')
    : '风';
  return getElementSvgUrl(ele);
}

