// ==================== 原神元素徽章（游戏原版素材，本地化） ====================
// 素材由 crawl_assets.py 从 enka.network 爬取到本地 assets/img/elements/，绕过 CORS/ORB
const ELEMENT_CDN_MAP = {
  '火': 'UI_Element_Fire.png',
  '水': 'UI_Element_Water.png',
  '冰': 'UI_Element_Ice.png',
  '雷': 'UI_Element_Electric.png',
  '风': 'UI_Element_Wind.png',
  '岩': 'UI_Element_Rock.png',
  '草': 'UI_Element_Grass.png',
  '多元素': 'UI_Element_Wind.png'
};
// 元素中文 → 英文（用于 SVG 兜底文件名）
const ELEMENT_EN_MAP = {
  '火': 'fire', '水': 'water', '冰': 'ice', '雷': 'electric',
  '风': 'wind', '岩': 'rock', '草': 'grass', '多元素': 'wind'
};
const CDN_BASE = 'assets/img/elements/';

// 生成游戏原版元素徽章（使用本地官方 PNG 素材，加载失败则隐藏）
function elementEmblem(element, size) {
  size = size || 28;
  const EC = (typeof ELEMENT_COLORS !== 'undefined') ? ELEMENT_COLORS : null;
  const color = (EC && EC[element]) || '#9B8E7B';
  const iconName = ELEMENT_CDN_MAP[element] || 'UI_Element_Wind.png';
  return `<img src="${CDN_BASE}${iconName}" class="ele-emblem-img" width="${size}" height="${size}" alt="${element}" style="filter:drop-shadow(0 0 4px ${color}44);" onerror="this.style.display='none'"/>`;
}

// 生成45°菱形元素指示器（游戏原版素材，加载失败则隐藏）
function elementDiamond(element, size) {
  size = size || 14;
  const EC = (typeof ELEMENT_COLORS !== 'undefined') ? ELEMENT_COLORS : null;
  const color = (EC && EC[element]) || '#9B8E7B';
  const iconName = ELEMENT_CDN_MAP[element] || 'UI_Element_Wind.png';
  return `<span class="ele-diamond" style="width:${size}px;height:${size}px;border-color:${color};">
    <span class="ele-diamond-inner" style="background:${color}22;"><img src="${CDN_BASE}${iconName}" width="${size}" height="${size}" style="opacity:0.8;" onerror="this.style.display='none';"/></span>
  </span>`;
}

