// 工具函数
const rColor = id => REGIONS.find(r => r.id === id)?.color || '#999';
const rName  = id => REGIONS.find(r => r.id === id)?.name  || id;
const rVer   = id => REGIONS.find(r => r.id === id)?.version || '';
const fmt    = n  => n >= 10000 ? (n/10000).toFixed(1)+'万' : n >= 1000 ? (n/1000).toFixed(1)+'k' : n+'';

const getElementClass = element => {
  // 火→水→冰→雷→风→岩→草
  const map = { '火': 'fire', '水': 'water', '冰': 'ice', '雷': 'electric', '风': 'wind', '岩': 'rock', '草': 'grass' };
  return map[element] || '';
};

const getWeaponClass = weapon => {
  const map = { '单手剑': 'sword', '双手剑': 'claymore', '长柄武器': 'polearm', '弓': 'bow', '法器': 'catalyst' };
  return map[weapon] || '';
};

// ==================== 武器类型图标（原神游戏原版素材，本地化） ====================
// 素材由 fetch_ui_assets.py 从 enka.network 爬取到本地 assets/img/deco/，绕过 CORS/ORB
// UI_ItemIcon_101~105 对应原神游戏内的五种武器类型图标
const WEAPON_ICON_MAP = {
  '单手剑': 'assets/img/deco/UI_ItemIcon_101.png',
  '双手剑': 'assets/img/deco/UI_ItemIcon_102.png',
  '长柄武器': 'assets/img/deco/UI_ItemIcon_103.png',
  '弓': 'assets/img/deco/UI_ItemIcon_104.png',
  '法器': 'assets/img/deco/UI_ItemIcon_105.png'
};

/**
 * 根据武器类型中文名返回其官方图标 URL
 * @param {string} weapon 武器类型（单手剑/双手剑/长柄武器/弓/法器）
 * @return {string} 官方 PNG 图标路径，无匹配返回 ''
 */
function getWeaponIconUrl(weapon) {
  return (WEAPON_ICON_MAP && WEAPON_ICON_MAP[weapon]) || '';
}

// ===== 安全渲染兼容（在 optimize.js 加载前提供基础实现） =====
window.safeRender = window.safeRender || function(containerId, renderFn, fallbackHtml) {
  try {
    renderFn();
  } catch (err) {
    console.error('[safeRender] 渲染失败:', err);
    if (containerId) {
      const container = typeof containerId === 'string' ? document.getElementById(containerId) : containerId;
      if (container) {
        container.innerHTML = fallbackHtml || `
          <div style="text-align:center;padding:48px 24px;color:var(--text-secondary);">
            <div style="font-size:18px;font-weight:600;color:var(--gold-light);margin-bottom:8px;">内容加载失败</div>
            <div style="font-size:13px;color:var(--text-tertiary);">${err.message || '未知错误'}</div>
          </div>`;
      }
    }
  }
};

